/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: TrackTableRow
 *   Functions: TrackTable
 * Internal
 *   Types: TrackTableProps
 * @end-catalog */

import type { ReactNode } from 'react';
import { AudioLines, Clock3 } from 'lucide-react';

import { Artwork } from './Artwork';
import { Icon } from './Icon';
import styles from './TrackTable.module.css';

/** One MediaTrack row; the page decides what activating it means and which controls it carries. */
export interface TrackTableRow {
  key: string;
  title: string;
  byline?: ReactNode;
  artworkUrl?: string | null;
  /** Playlist variant only: the Album cell, usually a link. */
  album?: ReactNode;
  duration: string | null;
  /** Set only on the player's current row: bars while playing, an accent number while paused. */
  state: 'playing' | 'paused' | null;
  disabled?: boolean;
  playLabel: string;
  onActivate: () => void;
  /** Revealed on hover or focus (always shown on touch): Room, Share, Add to Playlist. */
  actions?: ReactNode;
  /** Revealed like `actions`, but stays visible once the MediaTrack is saved. */
  save?: ReactNode;
  /** Revealed per-row menu after the duration (Playlist reorder and remove). */
  menu?: ReactNode;
}

interface TrackTableProps {
  variant: 'album' | 'playlist';
  /** Accessible name of the list. */
  label?: string;
  titleHeading: string;
  albumHeading?: string;
  /** Tooltip of the clock column. */
  durationHeading: string;
  rows: readonly TrackTableRow[];
}

/**
 * Shared Album and Playlist MediaTrack list: an aria-hidden column header over an ordered list of
 * rows. Each row's play button is a direct child of its `li` and stretches over the whole row, while
 * links and trailing controls stay its siblings, so nothing interactive nests inside the button.
 */
export const TrackTable = ({ variant, label, titleHeading, albumHeading, durationHeading, rows }: TrackTableProps) => (
  <div className={styles.table} data-variant={variant}>
    <div aria-hidden="true" className={styles.header} data-track-table-header="">
      <span className={styles.headerIndex}>#</span>
      <span>{titleHeading}</span>
      {variant === 'playlist' && <span className={styles.headerAlbum}>{albumHeading}</span>}
      <span className={styles.headerDuration} title={durationHeading}>
        <Clock3 aria-hidden="true" focusable="false" size={16} />
      </span>
    </div>
    <ol aria-label={label} className={styles.list}>
      {rows.map((row, index) => (
        <li
          className={styles.row}
          data-playback-state={row.state ?? undefined}
          data-unavailable={row.disabled || undefined}
          key={row.key}
        >
          <button
            aria-current={row.state ? 'true' : undefined}
            aria-label={row.playLabel}
            className={styles.rowButton}
            disabled={row.disabled}
            onClick={row.onActivate}
            type="button"
          >
            {/* The number, play or pause glyph and bars share one grid cell and cross-fade. */}
            <span aria-hidden="true" className={styles.indexNumber}>{index + 1}</span>
            {!row.disabled && <Icon className={styles.indexIcon} name={row.state === 'playing' ? 'pause' : 'play'} size={16} />}
            {row.state === 'playing' && (
              <AudioLines aria-hidden="true" className={styles.trackPlaybackBars} focusable="false" strokeWidth={1.9} />
            )}
          </button>
          <div className={styles.titleCell}>
            {variant === 'playlist' && (
              <Artwork alt="" className={styles.thumb} kind="audioTrack" sizes="2.5rem" src={row.artworkUrl} />
            )}
            <span className={styles.copy}>
              <span className={`${styles.trackTitle} ${row.state ? styles.trackTitlePlaying : ''}`} title={row.title}>
                {row.title}
              </span>
              {row.byline && <span className={styles.byline}>{row.byline}</span>}
            </span>
          </div>
          {variant === 'playlist' && <div className={styles.albumCell}>{row.album}</div>}
          <div className={styles.trailing}>
            {row.actions && <span className={styles.reveal}>{row.actions}</span>}
            {row.save && <span className={styles.reveal}>{row.save}</span>}
            <span className={styles.duration}>{row.duration || '—'}</span>
            {row.menu && <span className={styles.reveal}>{row.menu}</span>}
          </div>
        </li>
      ))}
    </ol>
  </div>
);
